            UNION ALL
            SELECT (pg_catalog.hashtext(u._above) & 1023) * 5, false FROM unnest(p_under, p_hung) u(_above, _hung) WHERE u._above IS NOT NULL
            UNION ALL
            SELECT (pg_catalog.hashtext(u._above) & 1023) * 5 + 1 + ((pg_catalog.hashtext(u._hung) >> 12) & 3), true
