      SELECT o._slot, o._upd,
             CASE WHEN o._slot = -1 THEN (SELECT 1 FROM authz_int.locks l WHERE l.type = p_type FOR SHARE SKIP LOCKED)
                  WHEN o._upd THEN (SELECT 1 FROM authz_int.tree_locks_1024_4 t
