                  ELSE (SELECT 1 FROM authz_int.tree_locks_1024_4 t
                        WHERE t.type = p_type AND t.slot = o._slot FOR SHARE SKIP LOCKED) END AS _held
      FROM (SELECT n._slot, n._upd FROM need n ORDER BY n._slot OFFSET 0) o),
